package com.mechwild.mechs.client;
import com.mechwild.mechs.MechwildMechs; import com.mojang.blaze3d.vertex.PoseStack; import com.mojang.blaze3d.vertex.VertexConsumer; import net.minecraft.client.model.HierarchicalModel; import net.minecraft.client.model.geom.ModelLayerLocation; import net.minecraft.client.model.geom.ModelPart; import net.minecraft.client.model.geom.PartPose; import net.minecraft.client.model.geom.builders.CubeListBuilder; import net.minecraft.client.model.geom.builders.LayerDefinition; import net.minecraft.client.model.geom.builders.MeshDefinition; import net.minecraft.client.model.geom.builders.PartDefinition; import net.minecraft.resources.ResourceLocation; import net.minecraft.util.Mth; import net.minecraft.world.entity.Entity;
public class RaptorMechModel<T extends Entity> extends HierarchicalModel<T> { public static final ModelLayerLocation LAYER_LOCATION = new ModelLayerLocation(new ResourceLocation(MechwildMechs.MODID, "raptor_mech"), "main"); private final ModelPart root, head, leftLeg, rightLeg, leftArm, rightArm, tail; public RaptorMechModel(ModelPart root) { this.root = root; this.head = root.getChild("head"); this.leftLeg = root.getChild("left_leg"); this.rightLeg = root.getChild("right_leg"); this.leftArm = root.getChild("left_arm"); this.rightArm = root.getChild("right_arm"); this.tail = root.getChild("tail"); } public static LayerDefinition createBodyLayer() { MeshDefinition mesh = new MeshDefinition(); PartDefinition root = mesh.getRoot(); root.addOrReplaceChild("body", CubeListBuilder.create().texOffs(0, 0).addBox(-6, -8, -10, 12, 10, 20), PartPose.offset(0, 12, 0)); root.addOrReplaceChild("head", CubeListBuilder.create().texOffs(0, 30).addBox(-4, -5, -8, 8, 7, 9), PartPose.offset(0, 8, -11)); root.addOrReplaceChild("left_leg", CubeListBuilder.create().texOffs(35, 30).addBox(-2, 0, -2, 4, 10, 4), PartPose.offset(4, 14, 5)); root.addOrReplaceChild("right_leg", CubeListBuilder.create().texOffs(35, 30).addBox(-2, 0, -2, 4, 10, 4), PartPose.offset(-4, 14, 5)); root.addOrReplaceChild("left_arm", CubeListBuilder.create().texOffs(52, 30).addBox(-2, 0, -2, 4, 8, 4), PartPose.offset(5, 14, -5)); root.addOrReplaceChild("right_arm", CubeListBuilder.create().texOffs(52, 30).addBox(-2, 0, -2, 4, 8, 4), PartPose.offset(-5, 14, -5)); root.addOrReplaceChild("tail", CubeListBuilder.create().texOffs(0, 47).addBox(-2, -2, 0, 4, 4, 14), PartPose.offset(0, 10, 10)); return LayerDefinition.create(mesh, 96, 64); } @Override public ModelPart root() { return root; } @Override public void setupAnim(T entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) { head.yRot = netHeadYaw * ((float)Math.PI / 180F); head.xRot = headPitch * ((float)Math.PI / 180F); rightLeg.xRot = Mth.cos(limbSwing * 0.6662F) * 1.0F * limbSwingAmount; leftLeg.xRot = Mth.cos(limbSwing * 0.6662F + (float)Math.PI) * 1.0F * limbSwingAmount; rightArm.xRot = Mth.cos(limbSwing * 0.6662F + (float)Math.PI) * 0.8F * limbSwingAmount; leftArm.xRot = Mth.cos(limbSwing * 0.6662F) * 0.8F * limbSwingAmount; tail.yRot = Mth.sin(ageInTicks * 0.12F) * 0.15F; } @Override public void renderToBuffer(PoseStack poseStack, VertexConsumer vertexConsumer, int packedLight, int packedOverlay, float red, float green, float blue, float alpha) { root.render(poseStack, vertexConsumer, packedLight, packedOverlay, red, green, blue, alpha); } }
